import { StorageType } from '@castify/record-mv3/common';
import { deleteRecordingDataById } from '@castify/record-mv3/recording-indexed-db';
import { Instance, types, getSnapshot } from 'mobx-state-tree';
import { ControllerStorageDriver } from '../controller/storage/ControllerStorageDriver';
import { useAuthStore } from '@castify/record-mv3/common/stores';
interface Metadata {
  driveFileId?: string;
  videoRegistryId?: string;
  extensionVmpId?: string;
  duration?: number;
  creationTime?: number;
  title: string;
  metadata?: GDriveMetadata;
  source?: StorageType; // For now, should default to `drive`
  mimeType?: string;
}

interface GDriveProperty {
  key: string;
  visibility: 'PRIVATE';
  value: boolean | string | number;
}

export interface GDriveMetadata {
  title: string;
  name: string;
  description: string;
  id: string;
  mimeType: string;
  properties: GDriveProperty[];
}

interface Recording {
  id: string;
  autoUpload: boolean;
  userId: string;
  orgId?: string;
  metadata: Metadata;
}

const Metadata = types.model({
  driveFileId: types.optional(types.string, ''),
  videoRegistryId: types.optional(types.string, ''),
  extensionVmpId: types.optional(types.string, ''),
  duration: types.optional(types.number, 0),
  creationTime: types.optional(types.number, 0),
  title: types.optional(types.string, ''),
  metadata: types.frozen(), // New property, 'any' type corresponds to types.frozen() which can accept any JSON-serializable data
  source: types.optional(types.string, 'drive'),
  mimeType: types.optional(types.string, 'video/webm; codecs="vp8, opus"'),
});

const Recording = types
  .model({
    id: types.optional(types.string, ''),
    autoUpload: types.optional(types.boolean, true),
    userId: types.optional(types.string, ''),
    orgId: types.optional(types.string, ''),
    attempts: types.optional(types.number, 0),
    metadata: types.optional(Metadata, {}),
  })
  .actions((self) => {
    return {
      updateMetadata(metadata: Partial<Metadata>): void {
        self.userId = useAuthStore.getState().userId ?? '';
        self.metadata = {
          ...self.metadata,
          ...metadata,
        };
      },
      resetAttempts(): void {
        self.attempts = 0;
      },
      incrementAttempts(): void {
        self.attempts += 1;
      },
    };
  });

export const RecordingStore = types
  .model('RecordingStore', {
    recoveryRecording: types.maybeNull(Recording),
    recordingList: types.optional(types.array(Recording), []),
  })
  .views((self) => {
    return {
      getRecordingById(id: string) {
        const recording = this.getRecordingList().find(
          (recording) => id === recording.id,
        );
        return recording;
      },
      getRecordingByVideoRegistryId(id: string) {
        const recording = this.getRecordingList().find(
          (recording) => id === recording.metadata.videoRegistryId,
        );
        return recording;
      },
      isEmpty() {
        return this.getRecordingList().length === 0;
      },
      hasRecordingsToUpload() {
        // Returns if there are recordings to upload in the recordingList
        return !!this.getRecordingList().find(({ autoUpload }) => autoUpload);
      },
      getRecordingList() {
        // Return the current user's videos only
        // Need to allow falsey otherwise all current videos will be come unavailable post update
        return self.recordingList.filter(
          (recording) =>
            recording.userId === useAuthStore.getState().userId ||
            !recording.userId,
        );
      },
      getLastRecording() {
        return this.getRecordingList()[this.getRecordingList().length - 1];
      },
      incrementAttempts(recordingId: string) {
        const currentRecording = self.recordingList.find(
          ({ id }) => id === recordingId,
        );
        if (!currentRecording) return;
        currentRecording.incrementAttempts();
      },
      resetAttempts() {
        this.getRecordingList().forEach((recording) => {
          recording.resetAttempts();
        });
      },
      getNextRecordingToUpload() {
        let nextRecording = this.getRecordingList()
          .slice()
          .reverse()
          .find(({ autoUpload, attempts }) => autoUpload && attempts < 3);

        if (!nextRecording) {
          this.resetAttempts();

          nextRecording = this.getRecordingList()
            .slice()
            .reverse()
            .find(({ autoUpload }) => autoUpload);
        }

        if (nextRecording) {
          this.incrementAttempts(nextRecording.id);
        }

        return nextRecording;
      },
    };
  })
  .actions((self) => {
    return {
      async addRecording(recording: Recording): Promise<void> {
        const currentRecording = self
          .getRecordingList()
          .find(({ id }) => id === recording.id);
        if (!currentRecording) self.recordingList.push(recording);
        else this.updateMetadataById(recording.id, recording.metadata);
        await ControllerStorageDriver.replaceRecordingStore(getSnapshot(self));
      },

      async removeRecording(id: string): Promise<void> {
        const index = self.recordingList.findIndex(
          (recording) => id === recording.id,
        );
        if (index === -1) {
          // remove recording not found;
          return;
        }
        self.recordingList.splice(index, 1);
        await deleteRecordingDataById(id);
        await ControllerStorageDriver.replaceRecordingStore(getSnapshot(self));
      },

      async updateMetadataById(id: string, metadata: Metadata): Promise<void> {
        const recording = self.recordingList.find(
          (recording) => id === recording.id,
        );
        if (!recording) return;
        recording.updateMetadata(metadata);
        await ControllerStorageDriver.replaceRecordingStore(getSnapshot(self));
      },

      async saveRecoveryRecording() {
        const { recoveryRecording } = self;
        if (!recoveryRecording) return;
        self.recordingList.push({
          id: recoveryRecording.id,
          autoUpload: recoveryRecording.autoUpload,
          userId: useAuthStore.getState().userId ?? '',
          orgId: recoveryRecording.orgId,
          attempts: 0,
          metadata: {
            driveFileId: '',
            extensionVmpId: recoveryRecording.metadata.extensionVmpId,
            creationTime: recoveryRecording.metadata.creationTime,
            title: recoveryRecording.metadata.title,
            duration: recoveryRecording.metadata.duration,
            source: recoveryRecording.metadata.source,
            mimeType: recoveryRecording.metadata.mimeType,
          },
        });
        await this.removeRecoveryRecording();
        await ControllerStorageDriver.resetRecorderStatus();
        await ControllerStorageDriver.resetRecordingInProgress();
      },

      async toggleAutoUploadById(id: string) {
        const recording = self.recordingList.find(
          (recording) => id === recording.id,
        );
        if (!recording) return;
        recording.autoUpload = !recording.autoUpload;
        await ControllerStorageDriver.replaceRecordingStore(getSnapshot(self));
      },

      async updateRecoveryRecording(
        recording: Recording | null,
      ): Promise<void> {
        self.recoveryRecording = recording as IRecordingStoreRecord;
        await ControllerStorageDriver.replaceRecordingStore(getSnapshot(self));
      },

      async removeRecoveryRecording(): Promise<void> {
        if (self.recoveryRecording !== null) {
          self.recoveryRecording = null;
          await ControllerStorageDriver.replaceRecordingStore(
            getSnapshot(self),
          );
        }
      },
    };
  });
export type IRecordingStore = Instance<typeof RecordingStore>;
export type IRecordingStoreRecord = Instance<typeof Recording>;
