import { useCountdownStore } from '@castify/record-mv3/common/stores';
import styles from './Extension.styles';

export function CountdownOverlay() {
  const isVisible = useCountdownStore((s) => s.isVisible);
  const timeLeft = useCountdownStore((s) => s.timeLeft);

  if (!isVisible || timeLeft === null) return null;

  return (
    <div id="countdown-overlay" css={styles.countInOverlay}>
      <div css={styles.countInCircle}>
        <h1 css={styles.countInText}>{timeLeft}</h1>
      </div>
    </div>
  );
}
