import { useRef, useEffect } from 'react';
import { useWindowSize } from 'rooks';

export const useFullScreenCanvas = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const { innerWidth, innerHeight } = useWindowSize();

  useEffect(() => {
    if (canvasRef.current && innerWidth && innerHeight) {
      Object.assign(canvasRef.current.style, {
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
      });
      canvasRef.current.width = innerWidth * window.devicePixelRatio;
      canvasRef.current.height = innerHeight * window.devicePixelRatio;
      const ctx = canvasRef.current.getContext('2d');
      ctx?.scale(window.devicePixelRatio, window.devicePixelRatio);
    }
  }, [innerWidth, innerHeight]);

  return canvasRef;
};
