import { types } from 'mobx-state-tree';
import { Stickers } from '../consts/stickers';

export const StickersState = types
  .model('StickersState', {
    sticker: types.optional(
      types.union(
        types.literal('smile'),
        types.literal('sunglasses'),
        types.literal('heart-eyes'),
        types.literal('h100'),
        types.literal('thumbs-up'),
        types.literal('party'),
      ),
      'smile',
    ),
    size: 48,
  })
  .actions((self) => {
    return {
      setSticker(sticker: Stickers) {
        self.sticker = sticker;
      },
      setSize(size: number) {
        self.size = size;
      },
    };
  });
