import { useEffect } from 'react';
import { useCanvasState } from './useCanvasState';

interface CanvasCursorProps {
  default?: string;
  hover?: string;
  move?: string;
}

export const useCanvasCursor = ({
  default: defaultCursor,
  hover: hoverCursor,
  move: moveCursor,
}: CanvasCursorProps) => {
  const canvas = useCanvasState((s) => s.canvas);

  useEffect(() => {
    if (!canvas) return;

    canvas.defaultCursor = defaultCursor || 'auto';
    canvas.hoverCursor = hoverCursor || 'auto';
    canvas.moveCursor = moveCursor || 'auto';

    return () => {
      canvas.defaultCursor = 'auto';
      canvas.hoverCursor = 'auto';
      canvas.moveCursor = 'auto';
    };
  }, [canvas, defaultCursor, hoverCursor, moveCursor]);
};
