import Box from '@mui/material/Box';
import { ToolButton } from '../utility/ToolButton';
import BlurOnRoundedIcon from '@mui/icons-material/BlurOnRounded';
import { SHORTCUTS } from '../../consts/shortcuts';
import RemoveCircleOutlineRoundedIcon from '@mui/icons-material/RemoveCircleOutlineRounded';
import { removeActiveObject } from '../../state/canvas';

interface BlurToolsProps {
  isActive?: boolean;
  isExpanded?: boolean;
  onSelect?: () => void;
}

export const BlurTools = ({
  isActive,
  isExpanded,
  onSelect = () => {},
}: BlurToolsProps) => {
  if (!isActive && !isExpanded) return null;

  return isActive && isExpanded ? (
    <Box
      height="32px"
      display="flex"
      justifyContent="center"
      alignItems="center"
      gap="4px"
      border="1px solid #0000001F"
      borderRadius="16px"
      padding="0 1px"
      boxSizing="border-box"
      sx={{ background: '#EEEEEE' }}
    >
      <ToolButton
        data-pendo-event="MV3-clk-blur-mode"
        label={`Blur Tool (${SHORTCUTS['blur-tool'].label})`}
        isSelected
      >
        <BlurOnRoundedIcon />
      </ToolButton>
      <ToolButton label="Remove Blur (Delete)" onClick={removeActiveObject}>
        <RemoveCircleOutlineRoundedIcon />
      </ToolButton>
    </Box>
  ) : (
    <ToolButton
      data-pendo-event="MV3-clk-blur-mode"
      label={`Blur Tool (${SHORTCUTS['blur-tool'].label})`}
      onClick={onSelect}
      isSelected={isActive}
      isDefault
    >
      <BlurOnRoundedIcon />
    </ToolButton>
  );
};
