/**
 * Utility to determine reasonable encoding parameters given type of content
 * being recorded and desired quality.
 */

import { useSettingsStore } from '../../stores';
import {
  BitratePreset,
  BitratePresetTable,
  H264_BITRATE_PRESETS,
  H264_CAM_BITRATE_PRESETS,
  VP8_BITRATE_PRESETS,
  VP8_CAM_BITRATE_PRESETS,
  VP9_BITRATE_PRESETS,
  VP9_CAM_BITRATE_PRESETS,
} from '../types/bitrate';
import { Codec, CODEC_VP8 } from '../types/codec';
import { RecordingType } from '../types/recording';
import { getSyncUseSafeVideoCodecFflag } from '../hooks/useSafeVideoCodecFflag';

// Mapping codec to bitrate table.
type CodecTable = { [k in Codec]: BitratePresetTable };

// All bitrates configs by codecs
const bitrateMap: CodecTable = {
  h264: H264_BITRATE_PRESETS,
  vp8: VP8_BITRATE_PRESETS,
  vp9: VP9_BITRATE_PRESETS,
};

const bitrateMapCam: CodecTable = {
  h264: H264_CAM_BITRATE_PRESETS,
  vp8: VP8_CAM_BITRATE_PRESETS,
  vp9: VP9_CAM_BITRATE_PRESETS,
};

const bppByContentAndCodec: Record<RecordingType, CodecTable> = {
  camera: bitrateMapCam,
  desktop: bitrateMap,
  tab: bitrateMap,
};

/**
 * Returns a supported video codec to be used with MediaRecorder.
 */
export function getSupportedVideoCodec(): Codec {
  const isSafeVideoCodecEnabled = getSyncUseSafeVideoCodecFflag();
  if (isSafeVideoCodecEnabled) return CODEC_VP8;

  if (!MediaRecorder?.isTypeSupported) return CODEC_VP8;

  const videoCodec = useSettingsStore.getState().defaultVideoCodec;
  if (MediaRecorder.isTypeSupported(`video/webm;codecs=${videoCodec}`)) {
    return videoCodec;
  }
  return CODEC_VP8;
}

/**
 * Return mime type to be used with MediaRecorder for use with given video codec.
 */
export function getMimeType(codec: Codec): string {
  return `video/webm; codecs="${codec}, opus"`;
}

/**
 * Get total bitrate from bitrate per pixel for given video track.
 * Read size of given video track and compute total bitrate.
 * @returns {number} 0 when the operation fails.
 */
export function getBitrate({
  height,
  width,
  codec,
  recordingType,
  bitratePreset,
}: {
  height: number;
  width: number;
  codec: Codec;
  recordingType: RecordingType;
  bitratePreset: BitratePreset;
}): number {
  const dimension = Math.sqrt(width * height); // Normalized dimension
  const table = bppByContentAndCodec[recordingType][codec][bitratePreset];

  let bitrate = -1;
  for (const [minDimension, rate] of table) {
    if (dimension >= minDimension) bitrate = rate;
    else break;
  }

  return bitrate < 0 ? 0 : bitrate * 1024 * 1024; // Mbps to bps
}

/**
 * Get the resolution of a video `MediaStreamTrack`.
 * @returns {object} `{ height: 0, width: 0 }` if an error occurs.
 */
export function getVideoResolution(videoTrack: MediaStreamTrack): {
  width: number;
  height: number;
} {
  const constraints = videoTrack.getConstraints();
  const width = (constraints.width as ULongRange)?.max;
  const height = (constraints.height as ULongRange)?.max;
  if (!(height && width)) {
    return { height: 0, width: 0 };
  } else {
    return { height, width };
  }
}
