import '@webcomponents/custom-elements';
import React, { StrictMode } from 'react';
import { createRoot, Root } from 'react-dom/client';
import { CacheProvider } from '@emotion/react';
import createCache from '@emotion/cache';
import { ControllerMstProvider } from '@castify/record-mv3/record-components';
import { ErrorBoundary } from 'react-error-boundary';
import {
  componentErrorHandler,
  ErrorFallback,
  OnUnhandledRejection,
} from '@castify/record-mv3/error-handling';
import { DrawingToolsProvider } from '@castify/record-mv3/drawing-tools';
import { SyncStoreProvider } from '@castify/record-mv3/common/stores';
import { PendoEventBridge } from '../../pendo/PendoEventBridge';

const FragmentElement = () => <></>;

export class CastifyShadowContainer extends HTMLElement {
  private root: ShadowRoot;
  private container = document.createElement('div');
  private reactRoot: Root | null = null;
  public RootElement: React.FC = FragmentElement;
  private CDN_FONTS_URL = 'https://cdn.castify.com/fonts/css/fonts.css';

  constructor() {
    super();

    if (this.shadowRoot) {
      this.root = this.shadowRoot;
    } else {
      this.root = this.attachShadow({ mode: 'open' });
    }
  }

  async connectedCallback() {
    this.root.innerHTML = '';
    const link = document.createElement('link');
    link.setAttribute('rel', 'stylesheet');
    link.setAttribute('href', this.CDN_FONTS_URL);
    this.root.append(link);

    const style = document.createElement('style');
    style.textContent = `
      *, *::before, *::after {
        font-family: 'Fellix', sans-serif !important;
      }
      :host {
        all: initial;
        font-size: 16px !important;
        display: block;
      }
      .MuiSvgIcon-root {
        font-size: 16px !important;
        width: 1.5em;
        height: 1.5em;
      }
    `;
    this.root.append(style);

    this.root.append(this.container);

    const cache = createCache({
      key: 'extension',
      container: this.root,
      prepend: true,
    });

    this.reactRoot = createRoot(this.container);
    this.reactRoot.render(
      <StrictMode>
        <CacheProvider value={cache}>
          <ErrorBoundary
            FallbackComponent={ErrorFallback}
            onError={componentErrorHandler}
          >
            <OnUnhandledRejection>
              <ControllerMstProvider>
                <SyncStoreProvider>
                  <DrawingToolsProvider withRouter={false}>
                    <PendoEventBridge>
                      <this.RootElement />
                    </PendoEventBridge>
                  </DrawingToolsProvider>
                </SyncStoreProvider>
              </ControllerMstProvider>
            </OnUnhandledRejection>
          </ErrorBoundary>
        </CacheProvider>
      </StrictMode>,
    );
  }

  disconnectedCallback() {
    if (this.reactRoot) this.reactRoot.unmount();
  }
}

if (!customElements.get('castify-shadow-container')) {
  customElements.define('castify-shadow-container', CastifyShadowContainer);
}
