import { types } from 'mobx-state-tree';
import { Box, Point, Transform } from '../components/tools/math';
import * as dom from '../components/tools/dom';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';
import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import {
  environment,
  getExtensionBrowserType,
} from '@castify/record-mv3/environment';

const currentVersion =
  chrome.runtime.getManifest().version_name + getExtensionBrowserType();
const logger = new ServiceWorkerLogger(
  environment.logServiceUrl,
  getFirebaseAccessToken,
  {
    appName: 'AnchorModel',
    buildId: currentVersion,
  },
);

/**
 * Find top-most element on point, while ignoring app-owned elements.
 * @param point on viewport.
 */
const elementAt = (point: Point): Element | null => {
  const pair = point.toPair();
  const elements = document.elementsFromPoint(...pair) || [];

  let el: Element | null =
    elements.find(
      (element) =>
        document.querySelector('castify-shadow-container') !== element,
    ) ?? null;

  let best: Element | null = el;

  while (el && el.shadowRoot) {
    const next = el.shadowRoot.elementFromPoint(...pair);
    if (next === el) break; // On M67 elementFromPoint returns element itself.
    el = next;
    if (el) best = el;
  }

  // if best element is an iframe, get the best element from the iframe
  if (best?.tagName === 'IFRAME') {
    const iframeElement = getElementFromIframe(
      best as HTMLIFrameElement,
      pair[0],
      pair[1],
    );
    if (iframeElement) best = iframeElement;
  }

  return best;
};

const getElementFromIframe = (
  iframe: HTMLIFrameElement,
  x: number,
  y: number,
): Element | null => {
  try {
    const iframeRect = iframe.getBoundingClientRect();
    const iframeDocument = iframe.contentDocument;
    const iframeWindow = iframe.contentWindow;

    if (iframeDocument || iframeWindow?.document) {
      const iframePoint = {
        x: x - iframeRect.left,
        y: y - iframeRect.top,
      };

      const iframeElements =
        iframeDocument?.elementsFromPoint(iframePoint.x, iframePoint.y) || [];
      return iframeElements.length ? iframeElements[0] : null;
    }
  } catch (err) {
    logger.warn('Cross-origin iframe detected, cannot access contents.', err);
  }

  return null;
};

/**
 * Get position of element in viewport as Point.
 * @returns position.
 */
const elementPosition = (el: Element) => {
  const box = el.getBoundingClientRect();
  return new Point(box.left, box.top);
};

const getBoundingBox = (el: Element) => {
  return Box.fromObject(el.getBoundingClientRect());
};

const findParentContaining = (el: Element, point: Point) => {
  let anchestor: Element | null = el;
  let box = getBoundingBox(anchestor);
  while (anchestor && (!box || !box.containsPoint(point))) {
    anchestor = anchestor.parentElement;
    if (anchestor) {
      box = getBoundingBox(anchestor);
    }
  }
  return anchestor;
};

export const AnchorModel = types
  .model('AnchorModel', {
    anchor: types.maybeNull(types.frozen<Element | null>()),
    defaultAnchorBox: types.maybeNull(types.frozen<Box | null>()),
    useViewport: types.optional(types.boolean, false),
  })
  .actions((self) => {
    return {
      recalculateAnchor(point: Point) {
        const { useViewport, anchor } = self;
        if (useViewport) return;
        if (!anchor) this.setDefaultAnchorBox(elementAt(point));
        else this.setDefaultAnchorBox(findParentContaining(anchor, point));
      },
      getCurrentAnchorBox(): Box {
        const { anchor } = self;
        if (!anchor) return dom.getViewportBox(); // Assuming dom exists
        return getBoundingBox(anchor);
      },
      setDefaultAnchorBox(el: Element | null) {
        try {
          const { useViewport, anchor } = self;
          if (useViewport || anchor === el) return;
          self.anchor = el;
          if (el === null) {
            self.useViewport = true;
          } else {
            self.defaultAnchorBox = getBoundingBox(el);
          }
        } catch (_) {
          /**
           * In some particular scenarios, the "anchor" and "defaultAnchorBox" elements cannot be frozen.
           * This throws an error in MobX. For this reason in these edge scenarios the value is ignored.
           */
        }
      },
      transformPointToView(point: Point) {
        const transform = this.transformToView();
        return transform.apply(point);
      },
      transformToAnchor() {
        return this.transformToView().inverse();
      },
      transformToView(): Transform {
        const { anchor, defaultAnchorBox } = self;
        if (!anchor || !defaultAnchorBox)
          return Transform.fromPoint(new Point(0, 0));
        const anchorPos = elementPosition(anchor);
        if (anchor !== document.body) {
          anchorPos.y -= defaultAnchorBox.top;
          anchorPos.x -= defaultAnchorBox.left;
        }
        return Transform.fromPoint(anchorPos);
      },
    };
  });
