import { useState, MouseEvent } from 'react';
import { observer } from 'mobx-react-lite';
import { Rnd } from 'react-rnd';
import { useControllerState } from '@castify/record-mv3/record-components';
import Box from '@mui/material/Box';
import IconButton from '@mui/material/IconButton';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import FullscreenRoundedIcon from '@mui/icons-material/FullscreenRounded';
import FullscreenExitRoundedIcon from '@mui/icons-material/FullscreenExitRounded';
import FlipRoundedIcon from '@mui/icons-material/FlipRounded';
import { colors } from '@cfy/fe-common';
import styles from './Extension.styles';

const DEFAULT_SIZE = {
  width: 300,
  height: 200,
};
const DEFAULT_POSITION = {
  x: window.innerWidth - DEFAULT_SIZE.width,
  y: window.innerHeight - DEFAULT_SIZE.height,
};

const stopProp = (e: MouseEvent) => e.stopPropagation();

export const InteractiveWebcam = observer(() => {
  const { recordingSettings } = useControllerState();
  const [isHover, setIsHover] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isFlipped, setIsFlipped] = useState(false);
  const [size, setSize] = useState(DEFAULT_SIZE);
  const [position, setPoisition] = useState(DEFAULT_POSITION);

  return (
    <Rnd
      default={{
        ...DEFAULT_POSITION,
        ...DEFAULT_SIZE,
      }}
      size={{
        width: isFullscreen ? '100%' : size.width,
        height: isFullscreen ? '100%' : size.height,
      }}
      position={{
        x: isFullscreen ? 0 : position.x,
        y: isFullscreen ? 0 : position.y,
      }}
      onDragStop={(_, { x, y }) => {
        setPoisition({ x, y });
      }}
      onResize={(_, __, ref, ___, newPosition) => {
        setSize({
          width: ref.offsetWidth,
          height: ref.offsetHeight,
        });
        setPoisition(newPosition);
      }}
      disableDragging={isFullscreen}
      enableResizing={!isFullscreen}
      minWidth={DEFAULT_SIZE.width}
      minHeight={DEFAULT_SIZE.height}
      bounds="window"
      style={{ pointerEvents: 'initial', userSelect: 'none' }}
    >
      <Box
        id="webcam"
        data-testid="webcam"
        position="relative"
        width="100%"
        height="100%"
        onMouseEnter={() => setIsHover(true)}
        onMouseLeave={() => setIsHover(false)}
        onClick={stopProp}
        onPointerDown={stopProp}
        onPointerUp={stopProp}
      >
        <iframe
          title="webcam"
          allow="camera; microphone; display-capture"
          src={chrome.runtime.getURL('/webcam.html')}
          css={styles.webcamIframe}
          style={{
            transform: isFlipped ? 'scaleX(-1)' : 'scaleX(1)',
          }}
        />
        <Box
          position="absolute"
          width="100%"
          display="flex"
          flexDirection="row-reverse"
          alignItems="center"
          gap="2px"
          boxSizing="border-box"
          padding="8px"
          sx={{
            background: 'linear-gradient(180deg, rgba(0,0,0,.6), transparent)',
            opacity: isHover ? 1 : 0,
            transition: 'opacity 0.2s ease-in-out',
          }}
        >
          <IconButton
            onClick={() => recordingSettings.setUseVideoDevice(false)}
            sx={{ color: colors.textPrimaryDark }}
          >
            <CloseRoundedIcon />
          </IconButton>
          <IconButton
            onClick={() => setIsFullscreen(!isFullscreen)}
            sx={{ color: colors.textPrimaryDark }}
          >
            {isFullscreen ? (
              <FullscreenExitRoundedIcon />
            ) : (
              <FullscreenRoundedIcon />
            )}
          </IconButton>
          <IconButton
            onClick={() => setIsFlipped(!isFlipped)}
            sx={{ color: colors.textPrimaryDark }}
          >
            <FlipRoundedIcon />
          </IconButton>
        </Box>
      </Box>
    </Rnd>
  );
});
