import { useState, PropsWithChildren } from 'react';
import {
  DrawingToolsContext,
  makeBlankContext,
} from './state/context/DrawingToolsContext';
import { ThemeProvider } from '@emotion/react';
import { theme } from '@cfy/fe-common';
import { DrawingToolsCanvas } from './DrawingToolsCanvas';
import { CursorCanvasProvider } from './providers/CursorCanvasProvider';

export const DrawingToolsProvider = ({
  children,
}: PropsWithChildren<Record<string, unknown>>) => {
  const [drawingToolsState] = useState(makeBlankContext);

  return (
    <ThemeProvider theme={theme}>
      <DrawingToolsContext.Provider value={drawingToolsState}>
        <CursorCanvasProvider>
          <DrawingToolsCanvas />
          {children}
        </CursorCanvasProvider>
      </DrawingToolsContext.Provider>
    </ThemeProvider>
  );
};
