import { useEffect } from 'react';
import { useCanvasState } from './useCanvasState';
import { useWheelEffect } from './useWheelEffect';

export const useFabricCanvas = () => {
  const canvasRef = useCanvasState((s) => s.canvasRef);

  useWheelEffect();

  useEffect(() => {
    if (!canvasRef?.current) return;

    const canvasEl = canvasRef.current;
    const parentElement = canvasEl.parentElement;
    const nextSibling = canvasEl.nextSibling as HTMLElement | null;

    canvasEl.style.pointerEvents = 'auto';
    parentElement && (parentElement.style.pointerEvents = 'auto');
    nextSibling && (nextSibling.style.pointerEvents = 'auto');

    return () => {
      if (!canvasRef?.current) return;

      canvasEl.style.pointerEvents = 'none';
      parentElement && (parentElement.style.pointerEvents = 'none');
      nextSibling && (nextSibling.style.pointerEvents = 'none');
    };
  }, [canvasRef]);

  return null;
};
