import {
  RESOLUTION_PRESETS,
  Resolution,
  ResolutionPreset,
} from '../types/resolution';

const getCurrentDisplayBounds = async () => {
  const currentWindow = await chrome.windows.getCurrent();
  const displayList = await chrome.system.display.getInfo();

  const { left = 0, top = 0 } = currentWindow;
  let currentDisplayBounds = displayList[0].bounds;
  if (displayList.length === 1) return currentDisplayBounds;
  for (const { bounds } of displayList) {
    if (
      left > bounds.left &&
      left < bounds.width &&
      top > bounds.top &&
      top < bounds.height
    ) {
      currentDisplayBounds = bounds;
      break;
    }
  }
  return currentDisplayBounds;
};

export const getScreenResolutionPresets = async () => {
  const { width, height } = await getCurrentDisplayBounds();
  return Object.entries(RESOLUTION_PRESETS).reduce((acc, [key, value]) => {
    if (value.width > width || value.height > height) return acc;
    return {
      ...acc,
      [key]: value,
    };
  }, {}) as Record<ResolutionPreset, Resolution>;
};
