import { useRef, useEffect } from 'react';

/**
 * A useRef that replaces ref.current when the value changes
 * across renders.
 *
 * Handy for situations where you need a ref to break out of closure,
 * AND always want the newest value.
 *
 * @param The value for the ref. If the value changes,
 * the new value will be assigned to ref.current.
 */
export function useUpdatingRef<T>(value: T) {
  const ref = useRef<T>(value);
  useEffect(() => void (ref.current = value), [value]);
  return ref;
}
