let isCreatingControllerTab = false;

export async function findOrCreateControllerTab() {
  if (isCreatingControllerTab) {
    const existingTabs = await chrome.tabs.query({
      url: `${window.location.origin}/controller.html`,
    });
    return existingTabs[0];
  }

  isCreatingControllerTab = true;
  const existingTabs = await chrome.tabs.query({
    url: `${window.location.origin}/controller.html`,
  });

  if (existingTabs.length === 0) {
    return chrome.tabs.create({
      url: 'controller.html',
      active: false,
      pinned: true,
    });
  }

  isCreatingControllerTab = false;
  return existingTabs[0];
}
