import { types } from 'mobx-state-tree';
import { Point2D } from './Point2D.mst';
import { STICKERS } from '../../components/cursorModes/sticker/Sticker';
import { AnchorModel } from '../AnchorModel.mst';
import { Point } from '../../components/tools/math';

export const StickerDrawing = types
  .model('Sticker', {
    anchorModel: types.optional(AnchorModel, { anchor: null }),
    position: Point2D,
    size: types.number,
    sticker: types.optional(
      types.union(
        types.literal('smile'),
        types.literal('sunglasses'),
        types.literal('heart-eyes'),
        types.literal('h100'),
        types.literal('thumbs-up'),
        types.literal('party'),
      ),
      'smile',
    ),
  })
  .actions((self) => {
    return {
      calculateAnchor(x: number, y: number) {
        self.anchorModel.recalculateAnchor(new Point(x, y));
      },
      drawTo(ctx: CanvasRenderingContext2D) {
        const { position, size, sticker, anchorModel } = self;
        let origin = new Point(position.x - size / 2, position.y + size / 3);

        if (anchorModel.anchor) {
          origin = anchorModel.transformPointToView(origin);
        }

        ctx.font = `${size}px Arial`;
        ctx.fillText(STICKERS[sticker], origin.x, origin.y);
      },
    };
  });
