import { useEffect } from 'react';
import { useStickersState } from '../state/context/useDrawingToolsState.hook';
import { SHORTCUTS } from '../consts/shortcuts';

const MIN_VALUE = 8;
const MAX_VALUE = 128;

export const useStickersResizeShortcuts = () => {
  const { setSize, size } = useStickersState();

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const { code } = e;
      e.preventDefault();

      if (
        code === SHORTCUTS['pointer-size-increase'].code ||
        code === SHORTCUTS['pointer-size-increase-2'].code
      ) {
        setSize(Math.min(MAX_VALUE, size + 2));
      }

      if (
        code === SHORTCUTS['pointer-size-decrease'].code ||
        code === SHORTCUTS['pointer-size-decrease-2'].code
      ) {
        setSize(Math.max(MIN_VALUE, size - 2));
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [size]);

  return null;
};
