import { Canvas } from 'fabric';
import { useEffect, useState } from 'react';
import { autorun, reaction } from 'mobx';
import { getSnapshot } from 'mobx-state-tree';
import { observer } from 'mobx-react-lite';
import {
  useDrawingState,
  useEraserState,
  usePenState,
  useRectangleState,
} from './state/context/useDrawingToolsState.hook';
import { useFullScreenCanvas } from './hooks/useFullScreenCanvas';
import Box from '@mui/material/Box';
import {
  useCanvasState,
  useIframeScrollSync,
  useSyncCanvas,
} from './state/canvas';
import { useLoadFonts } from './hooks/useLoadFonts';
import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';
import {
  environment,
  getExtensionBrowserType,
} from '@castify/record-mv3/environment';

const currentVersion =
  chrome.runtime.getManifest().version_name + getExtensionBrowserType();
const logger = new ServiceWorkerLogger(
  environment.logServiceUrl,
  getFirebaseAccessToken,
  {
    appName: 'DrawingToolsCanvas',
    buildId: currentVersion,
  },
);

export const DrawingToolsCanvas = observer(() => {
  const canvasRef = useFullScreenCanvas();
  const canvasTextRef = useFullScreenCanvas();
  const drawingState = useDrawingState();
  const penState = usePenState();
  const eraserState = useEraserState();
  const rectangleState = useRectangleState();
  const [animationFrameId, setAnimationFrameId] = useState<number>();
  const [setCanvas, setCanvasRef] = useCanvasState((s) => [
    s.setCanvas,
    s.setCanvasRef,
  ]);

  useLoadFonts();
  useSyncCanvas();

  const drawToCanvas = (ctx: CanvasRenderingContext2D) => {
    if (!canvasRef.current?.width || !canvasRef.current?.height) return;

    ctx.clearRect(0, 0, canvasRef.current.width, canvasRef.current.height);
    ctx.save();

    for (const element of drawingState.drawing) {
      element.drawTo(ctx);
    }
    penState.activePen?.drawTo(ctx);
    eraserState.activeEraser?.drawTo(ctx);
    rectangleState.activeRectangle?.drawTo(ctx);

    ctx.restore();
  };

  const drawOnIframeScroll = () => {
    if (!canvasRef.current) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;
    drawToCanvas(ctx);
  };
  useIframeScrollSync(drawOnIframeScroll);

  useEffect(() => {
    if (!canvasRef.current) return;
    if (!canvasTextRef.current) return;

    const fabricCanvas = new Canvas(canvasTextRef.current, {
      preserveObjectStacking: true,
      selection: false,
    });

    fabricCanvas.renderAll();
    setCanvas(fabricCanvas);
    setCanvasRef(canvasTextRef);

    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const draw = () => {
      if (animationFrameId) return;
      setAnimationFrameId(
        window.requestAnimationFrame(() => drawToCanvas(ctx)),
      );
    };

    autorun(draw);

    reaction(() => getSnapshot(drawingState), draw);
    reaction(() => getSnapshot(penState), draw);
    reaction(() => getSnapshot(eraserState), draw);
    reaction(() => getSnapshot(rectangleState), draw);

    window.addEventListener('scroll', draw, true);
    return () => {
      window.removeEventListener('scroll', draw, true);
      if (animationFrameId) window.cancelAnimationFrame(animationFrameId);
      if (fabricCanvas) {
        try {
          fabricCanvas.dispose();
        } catch (e) {
          logger.error(e);
        }
      }
    };
  }, []);

  return (
    <Box
      position="fixed"
      top={0}
      left={0}
      width="100%"
      height="100%"
      style={{ pointerEvents: 'none' }}
    >
      <canvas
        id="TextCanvas"
        data-testid="TextCanvas"
        ref={canvasTextRef}
        style={{
          pointerEvents: 'none',
        }}
      />
      <canvas
        id="DrawingToolsCanvas"
        data-testid="DrawingToolsCanvas"
        ref={canvasRef}
        style={{ pointerEvents: 'none' }}
      />
    </Box>
  );
});
