/**
 * Tries to resize tab to given size. Note that this might fail for example if
 * the screen is not large enough.
 * @param {Number} tabId tab id.
 * @param {Number} width in pixels
 * @param {Number} height in pixels.
 * @return {Promise} that resolves with tab details.
 */
export function resizeTabTo(tabId: number, width: number, height: number) {
  let tab: chrome.tabs.Tab | null = null;

  let errorOffsetWidth = 0;
  let errorOffsetHeight = 0;

  function updateTab() {
    return chrome.tabs.get(tabId).then((t) => {
      tab = t;
      return t;
    });
  }

  async function doResize() {
    if (!tab) return;
    return chrome.windows.get(tab.windowId).then((win) => {
      if (
        !(win && win.width && win.height) ||
        !(tab && tab.width && tab.height)
      )
        return;
      const marginWidth = win.width - tab.width;
      const marginHeight = win.height - tab.height;
      const winWidth = width + marginWidth + errorOffsetWidth;
      const winHeight = height + marginHeight + errorOffsetHeight;
      return chrome.windows.update(tab.windowId, {
        width: winWidth,
        height: winHeight,
        state: 'normal',
      });
    });
  }
  function checkSize(tab: chrome.tabs.Tab) {
    if (!(tab && tab.width && tab.height)) return;
    if (tab.width !== width || tab.height !== height) {
      errorOffsetWidth += width - tab.width;
      errorOffsetHeight += height - tab.height;
      return doResize().then(updateTab);
    }
    return tab;
  }

  return updateTab()
    .then(doResize)
    .then(updateTab)
    .then(checkSize)
    .catch(() => tab);
}
