import Box from '@mui/material/Box';
import { ToolButton } from '../utility/ToolButton';
import TextFieldsRoundedIcon from '@mui/icons-material/TextFieldsRounded';
import { SHORTCUTS } from '../../consts/shortcuts';
import RemoveCircleOutlineRoundedIcon from '@mui/icons-material/RemoveCircleOutlineRounded';
import { removeActiveObject } from '../../state/canvas';

interface TextToolsProps {
  isActive?: boolean;
  isExpanded?: boolean;
  onSelect?: () => void;
}

export const TextTools = ({
  isActive,
  isExpanded,
  onSelect = () => {},
}: TextToolsProps) => {
  if (!isActive && !isExpanded) return null;

  return isActive && isExpanded ? (
    <Box
      height="32px"
      display="flex"
      justifyContent="center"
      alignItems="center"
      gap="4px"
      border="1px solid #0000001F"
      borderRadius="16px"
      padding="0 1px"
      boxSizing="border-box"
      sx={{ background: '#EEEEEE' }}
    >
      <ToolButton
        data-pendo-event="MV3-clk-text-mode"
        label={`Text Tool (${SHORTCUTS['text-tool'].label})`}
        isSelected
      >
        <TextFieldsRoundedIcon />
      </ToolButton>
      <ToolButton label="Remove Text (Delete)" onClick={removeActiveObject}>
        <RemoveCircleOutlineRoundedIcon />
      </ToolButton>
    </Box>
  ) : (
    <ToolButton
      data-pendo-event="MV3-clk-text-mode"
      label={`Text Tool (${SHORTCUTS['text-tool'].label})`}
      onClick={onSelect}
      isSelected={isActive}
      isDefault
    >
      <TextFieldsRoundedIcon />
    </ToolButton>
  );
};
