import { Codec, CODEC_VP9 } from '../lib/types/codec';
import { createSyncStore } from './createSyncStore';
import { STORE_OPTIONS } from './utils';

interface SettingsStore {
  useQuickRecord: boolean;
  setUseQuickRecord: (useQuickRecord: boolean) => void;
  defaultVideoCodec: Codec;
  setDefaultVideoCodec: (codec: Codec) => void;
}

const INIT_STATE = {
  useQuickRecord: false,
  defaultVideoCodec: CODEC_VP9,
};

export const useSettingsStore = createSyncStore<SettingsStore>(
  'useSettingsStore',
  {
    ...INIT_STATE,

    setUseQuickRecord: (useQuickRecord: boolean) => {
      const { set } = useSettingsStore.getState();
      set({ useQuickRecord });
    },
    setDefaultVideoCodec: (defaultVideoCodec: Codec) => {
      const { set } = useSettingsStore.getState();
      set({ defaultVideoCodec });
    },
  },
  STORE_OPTIONS,
);
