import { createSyncStore } from './createSyncStore';
import { STORE_OPTIONS } from './utils';

interface User {
  userId: string | null;
  email: string | null;
  name: string | null;
}

interface AuthStore {
  userId: string | null;
  email: string | null;
  name: string | null;
  isAuth: boolean;
  // Tokens
  googleAccessToken?: string | null;
  firebaseAccessToken?: string | null;
  screencastifyToken?: string | null;
  isFirebaseTokenRefreshing: boolean;
  isEmailPwdUser: boolean;

  // setters
  setUserId: (userId: string) => void;
  setEmail: (email: string) => void;
  setName: (name: string) => void;
  setUser: (user: User) => void;
  setIsAuthentified: (isAuth: boolean) => void;
  resetUser: () => void;

  setGoogleAccessToken: (googleAccessToken: string | null) => void;
  setFirebaseAccessToken: (firebaseAccessToken: string | null) => void;
  setScreencastifyToken: (screencastifyToken: string | null) => void;
  setIsFirebaseTokenRefreshing: (isFirebaseTokenRefreshing: boolean) => void;
  setEmailPwdUser: (isEmailPwdUser: boolean) => void;
}

const INIT_STATE = {
  userId: '',
  email: '',
  name: '',
  googleAccessToken: null,
  firebaseAccessToken: null,
  screencastifyToken: null,
  isFirebaseTokenRefreshing: false,
  isAuth: false,
  isEmailPwdUser: false,
};

export const useAuthStore = createSyncStore<AuthStore>(
  'useAuthStore',
  {
    ...INIT_STATE,

    // setters
    setUserId: (userId: string) => {
      const { set } = useAuthStore.getState();
      set({ userId });
    },
    setEmail: (email: string) => {
      const { set } = useAuthStore.getState();
      set({ email });
    },
    setName: (name: string) => {
      const { set } = useAuthStore.getState();
      set({ name });
    },

    setGoogleAccessToken: (googleAccessToken: string | null) => {
      const { set } = useAuthStore.getState();
      set({ googleAccessToken });
    },
    setFirebaseAccessToken: (firebaseAccessToken: string | null) => {
      const { set } = useAuthStore.getState();
      set({ firebaseAccessToken, isFirebaseTokenRefreshing: false });
    },
    setScreencastifyToken: (screencastifyToken: string | null) => {
      const { set } = useAuthStore.getState();
      set({ screencastifyToken });
    },
    setIsFirebaseTokenRefreshing: (isFirebaseTokenRefreshing: boolean) => {
      const { set } = useAuthStore.getState();
      set({ isFirebaseTokenRefreshing });
    },

    setUser: (user: User) => {
      const { set } = useAuthStore.getState();
      set({ ...user });
    },
    setIsAuthentified: (isAuth: boolean) => {
      const { set } = useAuthStore.getState();
      set({ isAuth });
    },

    resetUser: () => {
      const { set } = useAuthStore.getState();
      set(INIT_STATE);
    },
    setEmailPwdUser: (isEmailPwdUser: boolean) => {
      const { set } = useAuthStore.getState();
      set({ isEmailPwdUser });
    },
  },
  STORE_OPTIONS,
);
