import { useEffect } from 'react';

export enum CURSOR_TYPE {
  PEN = 'PEN',
  RECTANGLE = 'RECTANGLE',
  ERASER = 'ERASER',
  NONE = 'none',
}

export interface CustomCursorParams {
  type: CURSOR_TYPE;
  cursor: string;
  color?: string;
}

export const useCustomCursor = ({
  type,
  cursor,
  color,
}: CustomCursorParams) => {
  const createCustomCursor = (cursorColor: string) => {
    const updatedSVGString = cursor.replace('cursorColor', cursorColor);
    const updatedBase64Data = Buffer.from(updatedSVGString).toString('base64');
    let updatedBase64Url;
    switch (type) {
      case CURSOR_TYPE.PEN:
        updatedBase64Url = `url("data:image/svg+xml;base64,${updatedBase64Data}") 0 18, auto`;
        break;
      case CURSOR_TYPE.RECTANGLE:
        updatedBase64Url = `url("data:image/svg+xml;base64,${updatedBase64Data}") 4 20, auto`;
        break;
      default:
        updatedBase64Url = 'default';
    }
    document.body.style.cursor = updatedBase64Url;
  };

  useEffect(() => {
    if (type === CURSOR_TYPE.PEN || type === CURSOR_TYPE.RECTANGLE) {
      color && createCustomCursor(color);
    } else {
      document.body.style.cursor = cursor;
    }
    return () => {
      document.body.style.cursor = 'default';
    };
  }, []);

  useEffect(() => {
    if (!color) return;
    createCustomCursor(color);
  }, [color]);

  return null;
};
