import { useRef, useEffect } from 'react';
import { reaction } from 'mobx';
import { useDrawingState } from '../state/context/useDrawingToolsState.hook';
import { useEvent } from './useEvent.hook';

// How often a fade happens
const TIME_BETWEEN_FADES = 30;

export const useFadeDrawing = () => {
  const windowRef = useRef(window);
  const drawingState = useDrawingState();
  const clearDrawingsTimeout = useRef<NodeJS.Timeout | null>(null);
  const fadeDrawingsTimeout = useRef<NodeJS.Timeout | null>(null);
  const fadeDrawingsInterval = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    reaction(
      () => drawingState.fadeTimer,
      () => {
        resetFadeTimeouts();
        if (drawingState.fadeTimer > 0) setFadeTimeouts();
      },
    );
    // only need to set up this reaction on intial render of the page no need to add extra deps
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const resetFadeTimeouts = () => {
    //clear out previous fade timers
    if (clearDrawingsTimeout.current)
      clearTimeout(clearDrawingsTimeout.current);
    if (fadeDrawingsTimeout.current) clearTimeout(fadeDrawingsTimeout.current);
    if (fadeDrawingsInterval.current)
      clearInterval(fadeDrawingsInterval.current);
    drawingState.resetFade();
  };

  const setFadeTimeouts = () => {
    // After 2 seconds, start fading
    fadeDrawingsTimeout.current = setTimeout(() => {
      // Calcluate how much the fade changes between every draw
      const fadeDeltaPerTick =
        TIME_BETWEEN_FADES / drawingState.fadeTimerDurations.fadeDuration;
      fadeDrawingsInterval.current = setInterval(() => {
        drawingState.setFade(drawingState.fade - fadeDeltaPerTick);
      }, TIME_BETWEEN_FADES);
    }, drawingState.fadeTimerDurations.timeToFade);

    // Clear all the pen drawings on the page after 3 seconds
    clearDrawingsTimeout.current = setTimeout(() => {
      drawingState.clearDrawing();
      if (fadeDrawingsTimeout.current)
        clearTimeout(fadeDrawingsTimeout.current);
      if (fadeDrawingsInterval.current)
        clearInterval(fadeDrawingsInterval.current);
    }, drawingState.timeToDisappear);
  };

  useEvent(windowRef, 'pointerdown', () => {
    resetFadeTimeouts();
  });

  useEvent(windowRef, 'pointerup', () => {
    if (drawingState.fadeTimer > 0) setFadeTimeouts();
  });

  return null;
};
