import { environment } from '@castify/record-mv3/environment';
import { safeWindowOpen } from '@cfy/fe-common';
import MenuIcon from '@mui/icons-material/MenuRounded';
import HomeRounded from '@mui/icons-material/HomeRounded';
import IconButton from '@mui/material/IconButton';
import AppBar from '@mui/material/AppBar';
import Toolbar from '@mui/material/Toolbar';
import Stack from '@mui/material/Stack';
import Tooltip from '@mui/material/Tooltip';
import { ReactNode, useRef, useState } from 'react';
import OptionsMenu from '../OptionsMenu/OptionsMenu';
import { CastifyLogo } from '../../../lib/components/Logo/CastifyLogo';
import { focusControllerTab } from '../../utils/focusControllerTab';

interface Props {
  leftSettings?: ReactNode;
  rightSettingsDrawer?: ReactNode;
  isLocalStorageRedirect?: boolean;
}

export function ControlPanelHeader({
  rightSettingsDrawer = null,
  isLocalStorageRedirect = false,
  leftSettings = null,
}: Props) {
  const [open, setOpen] = useState(false);
  const anchorRef = useRef<HTMLButtonElement>(null);

  const toggleMenu = () => {
    setOpen((prevOpen) => !prevOpen);
  };

  const handleClose = (event: Event) => {
    if (
      anchorRef.current &&
      anchorRef.current.contains(event.target as HTMLElement)
    ) {
      return;
    }

    setOpen(false);
  };

  return (
    <AppBar
      color="transparent"
      position="static"
      sx={{ borderRadius: 'initial', boxShadow: 'none' }}
    >
      <Toolbar
        sx={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          boxSizing: 'border-box',
          padding: '16px 24px',
          minHeight: 'fit-content',
        }}
      >
        <Stack
          direction="row"
          gap="16px"
          minWidth={!rightSettingsDrawer ? 'auto' : '80px'}
        >
          <IconButton
            color="info"
            size="small"
            sx={{ padding: '4px' }}
            ref={anchorRef}
            onClick={toggleMenu}
            data-testid="control-panel-header-options"
          >
            <MenuIcon />
          </IconButton>
          {leftSettings}
        </Stack>
        <OptionsMenu
          anchorEl={anchorRef.current}
          open={open}
          onClickAway={handleClose}
          isLocalStorageRedirect={isLocalStorageRedirect}
        />
        <CastifyLogo />
        <Stack direction="row" gap="16px">
          <Tooltip title="Home" placement="bottom">
            <IconButton
              color="info"
              size="small"
              sx={{
                padding: '4px',
                ml: !rightSettingsDrawer && leftSettings ? '48px' : 'auto',
              }}
              data-testid="control-panel-header-home"
              onClick={async () => {
                if (isLocalStorageRedirect) focusControllerTab();
                else safeWindowOpen(environment.externalLinks.homePage);
              }}
            >
              <HomeRounded />
            </IconButton>
          </Tooltip>
          {rightSettingsDrawer}
        </Stack>
      </Toolbar>
    </AppBar>
  );
}
