import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import MenuItem from '@mui/material/MenuItem';
import Stack from '@mui/material/Stack';
import Select from '@mui/material/Select';
import Typography from '@mui/material/Typography';
import { resizeTabTo } from '../utils/resizeTab';
import {
  ResolutionPreset,
  RESOLUTION_PRESETS,
  useScreenResolutionPresets,
} from '@castify/record-mv3/common';

export function ResizeTabSelect() {
  const [value, setValue] = useState<ResolutionPreset | ''>('');

  const { data } = useQuery(
    ['get-current-tab'],
    async () =>
      await chrome.tabs.query({ active: true, lastFocusedWindow: true }),
  );
  const currentTab = Array.isArray(data) ? data[0] : null;

  const resolutionPresets = useScreenResolutionPresets();

  return (
    <Select
      fullWidth
      size="small"
      value={value}
      onChange={(event) => {
        setValue(event.target.value as ResolutionPreset);
        if (!currentTab?.id) return;
        const newResolution =
          RESOLUTION_PRESETS[event.target.value as ResolutionPreset];
        resizeTabTo(currentTab.id, newResolution.width, newResolution.height);
      }}
      displayEmpty
      renderValue={(val) => {
        if (val === '') {
          return currentTab ? `${currentTab.width}x${currentTab.height}px` : '';
        } else {
          const { width, height } = RESOLUTION_PRESETS[val];
          return `${width}x${height}px`;
        }
      }}
    >
      {Object.entries(resolutionPresets).map(([key, value]) => (
        <MenuItem key={key} value={key}>
          <Stack direction="row" gap="8px">
            <Typography>{key}</Typography>
            <Typography variant="body2">
              {`(${value.width}x${value.height})`}
            </Typography>
          </Stack>
        </MenuItem>
      ))}
    </Select>
  );
}
