import { useEffect } from 'react';
import {
  useCursorModeState,
  useDrawingState,
} from '../state/context/useDrawingToolsState.hook';
import { MODES } from '../state/DrawingState.mst';
import { useControllerState } from '@castify/record-mv3/record-components';
import { SHORTCUTS } from '../consts/shortcuts';

export const useDrawingToolsShortcuts = () => {
  const { recordingSettings } = useControllerState();
  const { setMode, clearDrawing, setIsExpanded, isExpanded } =
    useDrawingState();
  const { setCursorMode } = useCursorModeState();

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const { altKey, code } = e;
      if (code === SHORTCUTS['close-tool'].code) setMode(MODES.CURSOR);

      if (!altKey) return;
      e.preventDefault();

      if (code === SHORTCUTS['pen-tool'].code) setMode(MODES.PEN);
      else if (code === SHORTCUTS['rectangle-tool'].code)
        setMode(MODES.RECTANGLE);
      else if (code === SHORTCUTS['eraser-tool'].code) setMode(MODES.ERASER);
      else if (code === SHORTCUTS['stickers-tool'].code) setMode(MODES.STICKER);
      else if (code === SHORTCUTS['text-tool'].code) setMode(MODES.TEXT);
      else if (code === SHORTCUTS['blur-tool'].code) setMode(MODES.BLUR);
      else if (code === SHORTCUTS['clear-canvas'].code) clearDrawing();
      else if (code === SHORTCUTS['classic-cursor'].code) {
        setMode(MODES.CURSOR);
        setCursorMode('classic');
      } else if (code === SHORTCUTS['focus-cursor'].code) {
        setMode(MODES.CURSOR);
        setCursorMode('focus');
      } else if (code === SHORTCUTS['clicks-cursor'].code) {
        setMode(MODES.CURSOR);
        setCursorMode('clicks');
      } else if (code === SHORTCUTS['fireworks-cursor'].code) {
        setMode(MODES.CURSOR);
        setCursorMode('fireworks');
      } else if (code === SHORTCUTS['toolbar-expand-collapse'].code) {
        setIsExpanded(!isExpanded);
      } else if (code === SHORTCUTS['toolbar-show-hide'].code) {
        recordingSettings?.setShowDrawingTools(
          !recordingSettings?.showDrawingTools,
        );
      } else if (code === SHORTCUTS['webcam-show-hide'].code) {
        recordingSettings?.setUseVideoDevice(!recordingSettings.useVideoDevice);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isExpanded, recordingSettings?.showDrawingTools]);

  return null;
};
