import { MouseEvent } from 'react';
import { observer } from 'mobx-react-lite';
import ChevronLeftIcon from '@mui/icons-material/ChevronLeft';
import ChevronRightIcon from '@mui/icons-material/ChevronRight';
import Divider from '@mui/material/Divider';
import { RecordingControls } from './components/utility/RecordingControls';
import { WebcamControls } from './components/utility/WebcamControls/WebcamControls';
import { useDragging } from './hooks/useDragging';
import { DragHandler } from './components/utility/DragHandler';
import styles from './DrawingTools.styles';
import { CursorTools } from './components/tools/CursorTools';
import { RectangleTools } from './components/tools/RectangleTools';
import { PenMode } from './components/modes/majorModes/PenMode';
import { RectangleMode } from './components/modes/majorModes/RectangleMode';
import { EraserMode } from './components/modes/majorModes/EraserMode';
import { CursorMode } from './components/modes/majorModes/CursorMode';
import { useFadeDrawing } from './hooks/useFadeDrawing';
import { PenTools } from './components/tools/PenTools';
import { EraserTools } from './components/tools/EraserTools';
import { ToolButton } from './components/utility/ToolButton';
import { ClearAllIcon } from './components/icons/ClearAllIcon';
import { useDrawingState } from './state/context/useDrawingToolsState.hook';
import { MODES } from './state/DrawingState.mst';
import { useDrawingToolsShortcuts } from './hooks/useDrawingToolsShortcuts';
import { SHORTCUTS } from './consts/shortcuts';
import { StickersTools } from './components/tools/StickersTools';
import { StickersMode } from './components/modes/majorModes/StickersMode';
import { TextMode } from './components/modes/majorModes/TextMode';
import { TextTools } from './components/tools/TextTools';
import { useCanvasState } from './state/canvas';
import { BlurTools } from './components/tools/BlurTools';
import { BlurMode } from './components/modes/majorModes/BlurMode';

const DEFAULT_TRANSPARENCY = 0.2;

const RENDER_MODE = {
  [MODES.PEN]: <PenMode />,
  [MODES.RECTANGLE]: <RectangleMode />,
  [MODES.STICKER]: <StickersMode />,
  [MODES.CURSOR]: null,
  [MODES.ERASER]: <EraserMode />,
  [MODES.TEXT]: <TextMode />,
  [MODES.BLUR]: <BlurMode />,
  [MODES.NONE]: <CursorMode />,
};

const stopProp = (e: MouseEvent) => e.stopPropagation();

export const DrawingTools = observer(() => {
  const { mode, setMode, isExpanded, setIsExpanded, clearDrawing } =
    useDrawingState();
  const clearCanvas = useCanvasState((s) => s.clearCanvas);

  const toggleExpendedTools = () => {
    setIsExpanded(!isExpanded);
  };

  const handleClearAll = () => {
    clearDrawing();
    clearCanvas();
  };

  const handleActiveMode = (newActiveMode: string) => {
    setIsExpanded(true);
    setMode(newActiveMode);
  };

  const handleEraserMode = () => {
    setIsExpanded(true);
    if (mode === MODES.ERASER) setMode(MODES.CURSOR);
    else setMode(MODES.ERASER);
  };

  useFadeDrawing();

  useDrawingToolsShortcuts();
  const { draggingRef, dragHandlerRef } = useDragging();

  return (
    <div
      ref={draggingRef}
      id="drawing-tools"
      data-testid="drawing-tools"
      css={styles.wrapper({
        opacity: DEFAULT_TRANSPARENCY,
      })}
    >
      <div
        css={styles.container}
        onClick={stopProp}
        onPointerDown={stopProp}
        onPointerUp={stopProp}
      >
        {RENDER_MODE[mode]}
        <RecordingControls />
        <Divider orientation="vertical" sx={{ height: '32px' }} />
        <CursorTools
          isActive={mode === MODES.CURSOR}
          isExpanded={isExpanded}
          onSelect={() => handleActiveMode(MODES.CURSOR)}
        />
        <RectangleTools
          isActive={mode === MODES.RECTANGLE}
          isExpanded={isExpanded}
          onSelect={() => handleActiveMode(MODES.RECTANGLE)}
        />
        <TextTools
          isActive={mode === MODES.TEXT}
          isExpanded={isExpanded}
          onSelect={() => handleActiveMode(MODES.TEXT)}
        />
        <BlurTools
          isActive={mode === MODES.BLUR}
          isExpanded={isExpanded}
          onSelect={() => handleActiveMode(MODES.BLUR)}
        />
        <PenTools
          isActive={mode === MODES.PEN}
          isExpanded={isExpanded}
          onSelect={() => handleActiveMode(MODES.PEN)}
        />
        <StickersTools
          isActive={mode === MODES.STICKER}
          isExpanded={isExpanded}
          onSelect={() => handleActiveMode(MODES.STICKER)}
        />
        <EraserTools
          isActive={mode === MODES.ERASER}
          isExpanded={isExpanded}
          onSelect={handleEraserMode}
        />
        {isExpanded && (
          <>
            <ToolButton
              data-pendo-event="MV3-clk-clear-all-canvas"
              label={`Clear All (${SHORTCUTS['clear-canvas'].label})`}
              onClick={handleClearAll}
            >
              <ClearAllIcon />
            </ToolButton>
            <Divider orientation="vertical" sx={{ height: '32px' }} />
            <WebcamControls />
          </>
        )}
        <ToolButton
          data-pendo-event={
            isExpanded ? 'MV3-clk-collapse-toolbar' : 'MV3-clk-expand-toolbar'
          }
          label={`${isExpanded ? 'Collapse' : 'Expand'} (${
            SHORTCUTS['toolbar-expand-collapse'].label
          })`}
          onClick={toggleExpendedTools}
        >
          {isExpanded ? <ChevronLeftIcon /> : <ChevronRightIcon />}
        </ToolButton>

        <DragHandler ref={dragHandlerRef} />
      </div>
    </div>
  );
});
