const EPS = 1e-10;

export class Point {
  constructor(public x: number, public y: number) {}

  toPair(): [number, number] {
    return [this.x, this.y];
  }

  add(other: Point) {
    return new Point(this.x + other.x, this.y + other.y);
  }

  sub(other: Point) {
    return new Point(this.x - other.x, this.y - other.y);
  }

  mul(scalar: number) {
    return new Point(this.x * scalar, this.y * scalar);
  }

  equals(other: Point) {
    return this.x === other.x && this.y === other.y;
  }
}

// Dot product with normal vector.
function perp(u: Point, v: Point) {
  return u.x * v.y - u.y * v.x;
}

/**
 * Line segment form a to b.
 * v = a + t * (b - a) for t = 0...1
 */
export class LineSegment {
  constructor(public a: Point, public b: Point) {}

  intersect(other: LineSegment) {
    const w = this.a.sub(other.a);
    const u = this.b.sub(this.a);
    const v = other.b.sub(other.a);
    const denominator = perp(u, v);
    // Collinear or degenrate, not a intersection for our purpose.
    if (Math.abs(denominator) < EPS) {
      return null;
    }
    const t = perp(v, w) / denominator;
    if (t > 1 || t < 0) {
      return null;
    }
    const tother = perp(u, w) / denominator;
    if (tother > 1 || tother < 0) {
      return null;
    }
    return this.a.add(u.mul(t));
  }
}

export class Box {
  get bottom() {
    return this.top + this.height;
  }

  get right() {
    return this.left + this.width;
  }

  static fromObject(obj: {
    left: number;
    top: number;
    width: number;
    height: number;
  }) {
    return new Box(obj.left, obj.top, obj.width, obj.height);
  }
  constructor(
    public left: number,
    public top: number,
    public width: number,
    public height: number,
  ) {}

  area() {
    return this.width * this.height;
  }

  /**
   * Check if box is contained in box (including borders).
   */
  containsPoint(point: Point) {
    return (
      this.left <= point.x &&
      point.x <= this.right &&
      this.top <= point.y &&
      point.y <= this.bottom
    );
  }

  /**
   * Check if box fully contains other box (i.e. the other box does not exeed this box's borders).
   */
  containsBox(box: Box) {
    return (
      this.left <= box.left &&
      box.right <= this.right &&
      this.top <= box.top &&
      box.bottom <= this.bottom
    );
  }

  clipLineSegment(segment: LineSegment) {
    const containsA = this.containsPoint(segment.a);
    const containsB = this.containsPoint(segment.b);
    // Shortcut for both ends inside / outside of box.
    if (containsA && containsB) {
      return segment;
    }
    if (!containsA && !containsB) {
      return null;
    }

    const corners = this.getCorners();
    let intersectionPoint;
    for (let i = 0; i < corners.length; ++i) {
      const line = new LineSegment(
        corners[i],
        corners[(i + 1) % corners.length],
      );
      intersectionPoint = line.intersect(segment);
      if (intersectionPoint) {
        break;
      }
    }
    if (intersectionPoint) {
      // Only one point is inside the box.
      const insidePoint = containsA ? segment.a : segment.b;
      return new LineSegment(insidePoint, intersectionPoint);
    }
    // eslint-disable-next-line no-console
    console.error('failed to clip line segment to box');
    return null;
  }

  /**
   * Computer intersection with other box.
   * @param other box.
   * @return intersection.
   */
  intersectBox(other: Box) {
    const top = Math.max(this.top, other.top);
    const left = Math.max(this.left, other.left);
    const bottom = Math.min(this.bottom, other.bottom);
    const right = Math.min(this.right, other.right);
    return new Box(
      left,
      top,
      Math.max(0, right - left),
      Math.max(0, bottom - top),
    );
  }

  /**
   * Corner points in clockwise order starting with top-left corner.
   */
  getCorners() {
    return [
      new Point(this.left, this.top),
      new Point(this.right, this.top),
      new Point(this.right, this.bottom),
      new Point(this.left, this.bottom),
    ];
  }

  /**
   * Return a copy of the box.
   */
  clone() {
    return new Box(this.left, this.top, this.width, this.height);
  }
}

// Just a translation for now.
export class Transform {
  /**
   * Create translation from point.
   */
  static fromPoint(point: Point) {
    return new Transform(point.x, point.y);
  }
  constructor(public x: number, public y: number) {}

  inverse() {
    return new Transform(-this.x, -this.y);
  }

  apply(point: Point) {
    // Not modifying the x for now
    return new Point(point.x + this.x, point.y + this.y);
  }
}

/**
 * Determinant of 3x3 row-first matrix.
 * @param mat 3x3 matrix.
 * @returns determinant.
 */
export function det3x3(mat: number[]) {
  const [a, b, c, d, e, f, g, h, i] = mat;
  return a * e * i + b * f * g + c * d * h - c * e * g - b * d * i - a * f * h;
}

export function det2x2(mat: number[]) {
  const [a, b, c, d] = mat;
  return a * d - b * c;
}

/**
 * Check if 3 points are in counter clockwise order.
 * @returns 0 if points are colinear,
 * 1 if oriented in counter-clockwise order,
 * -1 if oriented in clockwise order.
 */
export function ccw(a: Point, b: Point, c: Point) {
  return Math.sign(det3x3([a.x, b.x, c.x, a.y, b.y, c.y, 1, 1, 1]));
}
