import { CastifyLogoIcon } from '@castify/record-mv3/common';
import DeleteRoundedIcon from '@mui/icons-material/DeleteRounded';
import PauseRoundedIcon from '@mui/icons-material/PauseRounded';
import PlayArrowRoundedIcon from '@mui/icons-material/PlayArrowRounded';
import SettingsBackupRestoreRoundedIcon from '@mui/icons-material/SettingsBackupRestoreRounded';
import StopRoundedIcon from '@mui/icons-material/StopRounded';
import DescriptionRoundedIcon from '@mui/icons-material/DescriptionRounded';
import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import { observer } from 'mobx-react-lite';
import { RecordingManager } from '../../controller/commands/RecordingManager';
import { IRecording } from '../../state/recording.mst';
import { ControlButton } from '../buttons/ControlButton';
import styles from './WebcamPageControls.styles';

interface IWebCamPageControlsProps {
  recording: IRecording;
  onDelete: () => void;
  onRestart: () => void;
  useTeleprompter: boolean;
  showTeleprompter: boolean;
  onShowTeleprompterChange: () => void;
  recordingManager: RecordingManager;
}

export const WebcamPageControls = observer(
  ({
    recording,
    recordingManager,
    useTeleprompter,
    showTeleprompter,
    onDelete,
    onRestart,
    onShowTeleprompterChange,
  }: IWebCamPageControlsProps) => {
    return (
      <div css={styles.controls}>
        <div css={styles.leftContainer}>
          <CastifyLogoIcon />
          <div>
            <Typography>{recording.formattedDuration}</Typography>
          </div>
        </div>
        <div css={styles.verticalBar} />
        <Box
          sx={{
            display: 'flex',
            justifyContent: 'center',
            gap: '4px',
            mr: '16px',
          }}
        >
          {useTeleprompter && (
            <ControlButton
              Icon={DescriptionRoundedIcon}
              color={showTeleprompter ? 'primary' : 'info'}
              toolTipLabel={
                showTeleprompter ? 'Hide Teleprompter' : 'Show Teleprompter'
              }
              buttonLabel="Teleprompter"
              onClick={onShowTeleprompterChange}
            />
          )}
          <ControlButton
            Icon={DeleteRoundedIcon}
            toolTipLabel="Delete"
            buttonLabel="Delete"
            onClick={onDelete}
            disabled={
              recording.state !== 'recording' && recording.state !== 'paused'
            }
          />
          <ControlButton
            Icon={SettingsBackupRestoreRoundedIcon}
            toolTipLabel="Restart Recording"
            buttonLabel="Restart"
            onClick={onRestart}
            disabled={
              recording.state !== 'recording' && recording.state !== 'paused'
            }
          />
          {recording.state === 'paused' ? (
            <ControlButton
              Icon={PlayArrowRoundedIcon}
              color="success"
              toolTipLabel="Resume"
              buttonLabel="Resume"
              onClick={() => recordingManager.resumeRecording(recording)}
            />
          ) : (
            <ControlButton
              Icon={PauseRoundedIcon}
              toolTipLabel="Pause"
              buttonLabel="Pause"
              onClick={() => recordingManager.pauseRecording(recording)}
              disabled={recording.state !== 'recording'}
            />
          )}
          <ControlButton
            Icon={StopRoundedIcon}
            color="error"
            toolTipLabel="End Recording"
            buttonLabel="End"
            onClick={() => recordingManager.stopRecording(recording)}
            disabled={
              recording.state !== 'recording' && recording.state !== 'paused'
            }
          />
        </Box>
      </div>
    );
  },
);
