import { createBrowserLogger } from '@cfy/fe-monitoring';
import { CastifyShadowContainer } from './castify-shadow-container';
import { BaseDOMInjectionMessages } from './ScriptInjectionController';
import { createProtocolHandler } from '@castify/record-mv3/chrome-messaging';

// It is necessary to interact with the actual value for this,
// otherwise webpack tree-shakes it away.
void CastifyShadowContainer;
export class UnrecognizedMessage extends Error {
  constructor(public unrecognizedMessage: string) {
    super(`Unrecognized message to base-dom-injection ${unrecognizedMessage}`);
  }
}

export function renderInjectedReactElement(
  reactElement: React.FC,
  scriptName: string,
) {
  const logger = createBrowserLogger('renderInjectedReactElement');
  const container = document.createElement(
    'castify-shadow-container',
  ) as CastifyShadowContainer;

  container.style.position = 'absolute';
  container.style.zIndex = '2147483647';

  container.RootElement = reactElement;

  const protocolHandler = createProtocolHandler<BaseDOMInjectionMessages>({
    present: (message) => message.payload === scriptName,
    setup: () => {
      if (!container.parentElement) {
        document.body.append(container);
      }
    },
    teardown: () => {
      if (container.parentElement) {
        try {
          container.remove();
        } catch (e) {
          logger.error('failed to teardown container ', e);
        }
      }
    },
  });

  // As understood, this subscription will not out-live
  // the life time of the injection.
  //
  // If this code were to be moved to a non-injection context,
  // care should be taken to do any necessary cleanup with
  // chrome.runtime.OnMessage.removeListener(protocolHandler);
  chrome.runtime.onMessage.addListener(protocolHandler);
}
