import { useState } from 'react';
import { useEvent } from '../../../hooks/useEvent.hook';
import { styled } from '../../../styled';

interface ClickTargetCssProperties extends React.CSSProperties {
  '--size'?: string;
  '--clientX'?: number;
  '--clientY'?: number;
}

const ClickTarget = styled<ClickTargetCssProperties>('div', {
  '--size': '32px',
  '--clientX': 0,
  '--clientY': 0,

  pointerEvents: 'none',
  borderRadius: 'var(--size)',
  border: '3px solid red',
  width: 'var(--size)',
  height: 'var(--size)',
  zIndex: 100000,
  transform: 'translate(-50%, -50%)',
  position: 'fixed',
  left: 'calc(var(--clientX) * 1px)',
  top: 'calc(var(--clientY) * 1px)',
});

export const Clicks = () => {
  const windowRef = { current: window };

  const [clicking, setClicking] = useState(false);
  const [x, setX] = useState<number | null>(null);
  const [y, setY] = useState<number | null>(null);

  useEvent(windowRef, 'pointerdown', (event) => {
    setClicking(true);
    setX(event.clientX);
    setY(event.clientY);
  });

  useEvent(windowRef, 'pointermove', (event) => {
    setX(event.clientX);
    setY(event.clientY);
  });

  useEvent(windowRef, 'pointerup', () => {
    setClicking(false);
    setX(null);
    setY(null);
  });

  if (clicking && x !== null && y !== null) {
    return (
      <ClickTarget
        data-testid="ClickTarget"
        style={{
          '--clientX': x,
          '--clientY': y,
        }}
      />
    );
  }
  return null;
};
