import { createBrowserLogger, IBrowserLogger } from '@cfy/fe-monitoring';
import decodeJwt, { JwtPayload } from 'jwt-decode';

export const JWT_EXPIRATION_THRESHOLD = 300_000; // 5min
const logger: IBrowserLogger = createBrowserLogger(
  'shouldRefreshGoogleAccessToken',
);

/**
 * @desc Decode the google token and determine if it's time to refresh it.
 * @returns A boolean indicating whether or not the google accessToken should be refreshed
 */
export async function shouldRefreshGoogleAccessToken(
  googleAccessToken?: string | null,
  minutesToExpireCheck = 5,
): Promise<boolean> {
  const timeToCheck = minutesToExpireCheck * 60 * 1_000; // to ms
  if (!googleAccessToken) {
    return true;
  }
  // Call the Google token introspection endpoint
  try {
    const url = `https://www.googleapis.com/oauth2/v3/tokeninfo?access_token=${googleAccessToken}`;

    const response = await fetch(url);
    if (!response.ok) {
      logger.error(
        `Error fetching Google token info: ${
          response.status
        } ${await response.text()}`,
      );
      return true;
    }
    const data = await response.json();
    if (data.error) return true;

    const msUntilExpired = data.expires_in * 1_000;
    return msUntilExpired < timeToCheck;
  } catch (e) {
    logger.error(`Failed to check Google Access Token: ${e?.message}`);
    return true;
  }
}

/**
 * @desc Decode the JWT (if it exists) and determine if it's time to refresh it.
 * @returns A boolean indicating whether or not the JWT should be refreshed
 */
export function shouldRefreshJwt(
  jwt?: string | null,
  minutesToExpireCheck = 5,
): boolean {
  const timeToCheck = minutesToExpireCheck * 60 * 1_000; // to ms

  if (!jwt) return true;
  try {
    const decodedJwt = decodeJwt<JwtPayload>(jwt);
    const expiresAt = decodedJwt.exp ? decodedJwt.exp * 1_000 : Date.now();
    const msUntilExpired = expiresAt - Date.now();
    return msUntilExpired < timeToCheck;
  } catch (e) {
    logger.error(`Failed to check JWT: ${e?.message}`);
    return true;
  }
}

export async function checkGoogleDriveScopeAccess(
  googleAccessToken: string,
): Promise<boolean> {
  if (!googleAccessToken) {
    return true;
  }

  // Call the Google token introspection endpoint
  try {
    const url = `https://www.googleapis.com/oauth2/v3/tokeninfo?access_token=${googleAccessToken}`;
    const res = await fetch(url).then((res) => res.json());

    // Check if the token has the required scope
    const scope = res?.scope;
    if (!scope || !scope.includes('drive.file')) {
      logger.warn('Google access token does not have drive.file scope');
      return true;
    }

    return false;
  } catch (e) {
    logger.error(`Failed to check Google Access Token: ${e?.message}`);
    return false;
  }
}
