import { getParent, types } from 'mobx-state-tree';
import { Point2D } from './Point2D.mst';
import { DrawingState } from '../DrawingState.mst';
import { AnchorModel } from '../AnchorModel.mst';
import { Point } from '../../components/tools/math';

export const RectangleDrawing = types
  .model('Rectangle', {
    anchorModel: types.optional(AnchorModel, { anchor: null }),
    origin: Point2D,
    terminus: Point2D,
    color: types.string,
    size: types.number,
  })
  .actions((self) => {
    return {
      updateTerminus(x: number, y: number) {
        self.terminus = Point2D.create({ x, y });
        self.anchorModel.recalculateAnchor(new Point(x, y));
      },
      drawTo(ctx: CanvasRenderingContext2D) {
        const { origin, terminus, anchorModel, color, size } = self;
        let tOrigin = new Point(
          Math.min(origin.x, terminus.x),
          Math.min(origin.y, terminus.y),
        );
        let tTerminus = new Point(
          Math.max(origin.x, terminus.x),
          Math.max(origin.y, terminus.y),
        );

        if (anchorModel.anchor) {
          tOrigin = anchorModel.transformPointToView(tOrigin);
          tTerminus = anchorModel.transformPointToView(tTerminus);
        }

        ctx.save();
        const parentContext = getParent(self, 2);
        if (DrawingState.is(parentContext)) {
          ctx.globalAlpha = parentContext.fade;
        }
        ctx.lineCap = 'round';
        ctx.strokeStyle = color;
        ctx.lineWidth = size;
        ctx.strokeRect(
          tOrigin.x,
          tOrigin.y,
          tTerminus.x - tOrigin.x,
          tTerminus.y - tOrigin.y,
        );
        ctx.restore();
      },
    };
  });
