import { css } from '@emotion/react';

const styles = {
  brandedContainer: css`
    display: flex;
    justify-content: center;
    align-items: center;
    position: relative;
    width: 30px;
    height: 40px;
  `,
  animatedContainer: ({ isVisible }: { isVisible: boolean }) => css`
    position: absolute;
    display: flex;
    justify-content: center;
    align-items: center;
    opacity: ${isVisible ? 1 : 0};
    transform: ${isVisible ? 'scale(1)' : 'scale(0.3)'};
    transition: opacity 0.3s ease, transform 0.3s ease;
  `,
};

export default styles;
