import { AdditionalData, PendoMsg } from './types';

export const getPendoMsgFromEvent = (event: MouseEvent): PendoMsg => {
  const path = event.composedPath() as HTMLElement[];
  const target = path.find(
    (el) => el instanceof HTMLElement && el.hasAttribute('data-pendo-event'),
  ) as HTMLElement | undefined;

  if (!target) return {};

  const eventName = target.getAttribute('data-pendo-event');
  if (!eventName) return {};

  const additionalData: AdditionalData = {};

  Array.from(target.attributes).forEach((attr) => {
    if (
      attr.name.startsWith('data-pendo-') &&
      attr.name !== 'data-pendo-event'
    ) {
      const key = attr.name.replace('data-pendo-', '').replace(/-/g, '_');
      additionalData[key] = attr.value;
    }
  });

  return { eventName, additionalData };
};
