import { PropsWithChildren, useRef, useState } from 'react';
import { useEvent } from '../../../hooks/useEvent.hook';
import { styled } from '../../../styled';
import { useStickersState } from '../../../state/context/useDrawingToolsState.hook';
import { observer } from 'mobx-react-lite';
import { Stickers } from '../../../consts/stickers';

interface EmojiProps {
  sx?: object;
}

export const Emoji = ({ sx = {}, children }: PropsWithChildren<EmojiProps>) => {
  return (
    <div
      style={{ color: 'initial', fontSize: '18px', textAlign: 'center', ...sx }}
    >
      {children}
    </div>
  );
};

export const STICKERS: Record<Stickers, string> = {
  smile: '😊',
  sunglasses: '😎',
  'heart-eyes': '😍',
  h100: '💯',
  'thumbs-up': '👍',
  party: '🎉',
};

interface DrawingCircleProps extends React.CSSProperties {
  '--size'?: string;
  '--clientX'?: string;
  '--clientY'?: string;
}

const DrawingCircle = styled<DrawingCircleProps>('div', {
  '--size': '16px',
  '--clientX': '0px',
  '--clientY': '0px',

  background: 'transparent',
  pointerEvents: 'none',
  borderRadius: '50%',
  width: 'var(--size)',
  height: 'var(--size)',
  transform: 'translate(-50%, -50%)',
  position: 'fixed',
  left: 'var(--clientX)',
  top: 'var(--clientY)',
  boxSizing: 'border-box',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  textAlign: 'center',
});

export const Sticker = observer(() => {
  const windowRef = useRef(window);
  const { sticker, size } = useStickersState();

  const [x, setX] = useState<number | null>(null);
  const [y, setY] = useState<number | null>(null);

  useEvent(windowRef, 'pointermove', (event) => {
    setX(event.clientX);
    setY(event.clientY);
  });

  if (!x || !y) return null;

  return (
    <DrawingCircle
      data-testid="Sticker"
      style={{
        '--clientX': `${x}px`,
        '--clientY': `${y}px`,
        '--size': `${size}px`,
      }}
    >
      <Emoji sx={{ fontSize: `${size}px` }}>{STICKERS[sticker]}</Emoji>
    </DrawingCircle>
  );
});
