import { createSyncStore } from './createSyncStore';
import { STORE_OPTIONS } from './utils';

interface CountdownStore {
  isVisible: boolean;
  timeLeft: number | null;
  setVisible: (visible: boolean) => void;
  setTimeLeft: (seconds: number | null) => void;
  reset: () => void;
}

const INIT_STATE = {
  isVisible: false,
  timeLeft: null,
};

export const useCountdownStore = createSyncStore<CountdownStore>(
  'useCountdownStore',
  {
    ...INIT_STATE,

    setVisible: (isVisible) => {
      const { set } = useCountdownStore.getState();
      set({ isVisible });
    },

    setTimeLeft: (timeLeft) => {
      const { set } = useCountdownStore.getState();
      set({ timeLeft });
    },

    reset: () => {
      const { set } = useCountdownStore.getState();
      set({ ...INIT_STATE });
    },
  },
  STORE_OPTIONS,
);
