import {
  DrawingTools,
  CursorMode,
  useDrawingState,
  DrawingPointer,
  Sticker,
} from '@castify/record-mv3/drawing-tools';
import { useSyncedControllerState } from '@castify/record-mv3/record-components';
import { observer } from 'mobx-react-lite';
import { FreeTierRecordingAlert } from '../free-tier/FreeTierRecordingAlert';
import { InteractiveWebcam } from './InteractiveWebcam';
import { useFullscreenInjection } from './useFullscreenInjection';
import styles from './Extension.styles';
import { CountdownOverlay } from './CountdownOverlay';

const Extension = observer(() => {
  const { recordingSettings, userState, isRecording } =
    useSyncedControllerState();
  const { isDrawingMode, isStickerMode } = useDrawingState();

  useFullscreenInjection({ selector: 'castify-shadow-container' });

  if (!isRecording()) return null;

  return (
    <div
      id="extension-container"
      data-testid="extension-container"
      css={styles.wrapper}
    >
      {isDrawingMode() && <DrawingPointer />}
      {isStickerMode() && <Sticker />}
      <CursorMode />
      {recordingSettings.useCountIn && <CountdownOverlay />}
      {recordingSettings.useVideoDevice && !recordingSettings.pipEnabled && (
        <InteractiveWebcam />
      )}
      <div css={!recordingSettings.showDrawingTools && styles.hidden}>
        <DrawingTools />
      </div>
      {userState.hasUserData && userState.isFreeUser && (
        <div css={styles.freeTierRecordingAlert}>
          <FreeTierRecordingAlert />
        </div>
      )}
    </div>
  );
});

export default Extension;
